package com.demo.report
object DashboardMeasurements {
 import MeasurementMath._
 val schemaVersion="2.0"
 def build(samples:Seq[R],slates:Option[Seq[R]],live:Option[R],config:R):R={
  val support=n(config,"fairness_min_support").getOrElse(100d).toInt;val window=n(config,"freshness_window_days").getOrElse(30d).toInt;val tail=n(config,"long_tail_percentile").getOrElse(.8);val policy=config.getOrElse("safety_policy_version","catalog-filter-v1").toString
  require(support>0,"fairness-min-support must be a positive integer");require(window>=0,"freshness-window-days must be non-negative");require(tail>0&&tail<1,"long-tail-percentile must be between zero and one");require(policy.trim.nonEmpty,"safety-policy-version must not be blank")
  val hoisted=GovernanceMeasurements.dimensions.filterNot(k=>samples.exists(_.contains(k))).filter(k=>samples.exists(r=>features(r.getOrElse("user_features",null)).contains(k)))
  val measured=samples.map(r=>r++hoisted.map(k=>k->features(r.getOrElse("user_features",null)).getOrElse(k,null)))
  val snapshot=live.map(r=>if(r.contains("measurements"))obj(r("measurements"))else r).getOrElse(Map.empty)
  val noSlates=unavailable("missing slate experiences")
  Map("schemaVersion"->schemaVersion,"relevance"->slates.map(QualityMeasurements.relevance(_)).getOrElse(noSlates),"satisfaction"->merge(QualityMeasurements.satisfaction(measured),feedback(snapshot)),"freshness"->merge(QualityMeasurements.freshness(measured,config.getOrElse("now",null),window),freshness(snapshot)),"diversity"->slates.map(QualityMeasurements.diversity(_,tail,n(config,"catalog_size").map(_.toInt))).getOrElse(noSlates),"fairness"->GovernanceMeasurements.fairness(measured,support),"safety"->merge(GovernanceMeasurements.safety(measured,policy),safety(snapshot)),"latency"->latency(snapshot))
 }
 private def features(v:Any):R=v match{case m:Map[_,_]=>obj(m);case _=>seq(v).map(seq).filter(_.size==2).map(p=>p.head.toString->p(1)).toMap}
 private type Live=(R,Int,Double,String)
 private def merge(offline:R,entry:Option[Live]):R=entry.map{case(row,size,coverage,headline)=>if(offline("status")!="available")available(headline,Seq(row),size,coverage,seq(offline("warnings")).map(_.toString))else offline+("rows"->(seq(offline("rows")).map(v=>Map("scope"->"offline")++obj(v)):+row))}.getOrElse(offline)
 private def freshness(live:R):Option[Live]={val f=obj(live.getOrElse("freshness",null));val size=n(f,"exposures").getOrElse(0d).toInt;if(f.getOrElse("availability","")!="available"||size<=0)None else Some((Map("scope"->"live_service","freshness_source"->f.getOrElse("source",null),"fresh_share"->f.getOrElse("freshShare",null),"freshness_coverage"->f.getOrElse("coverage",null),"exposures"->f.getOrElse("exposures",null)),size,n(f,"coverage").getOrElse(0d),"Live fresh-item exposure"))}
 private def safety(live:R):Option[Live]={val f=obj(live.getOrElse("safety",null));val size=n(f,"evaluatedCandidates").getOrElse(0d).toInt;if(f.getOrElse("availability","")!="available"||size<=0)None else Some((Map("scope"->"live_service","policy_version"->f.getOrElse("policyVersion",null),"evaluated_candidates"->size,"filter_decisions"->f.getOrElse("totalDecisions",null),"filter_decision_rate"->n(f,"totalDecisions").map[Any](d=>ratio(d,size,false)).orNull,"reason_counts"->obj(f.getOrElse("reasons",null)).map{case(k,v)=>k->obj(v).getOrElse("count",null)},"unknown_share"->f.getOrElse("unknownShare",null)),size,.5,"Live candidate safety policy accounting"))}
 private def feedback(live:R):Option[Live]={val f=obj(live.getOrElse("feedbackCoverage",null));val size=n(f,"total").getOrElse(0d).toInt;if(f.getOrElse("availability","")!="available"||size<=0)None else {val signals=obj(f.getOrElse("signals",null));val columns=Seq("request_id"->"request_id_coverage","rating"->"rating_coverage","negative_feedback_reason"->"negative_feedback_coverage","dwell_millis"->"dwell_coverage","completion_rate"->"completion_coverage");val coverages=columns.map{case(sig,col)=>col->obj(signals.getOrElse(sig,null)).getOrElse("coverage",null)}.toMap;val observed=coverages.values.collect{case n:java.lang.Number=>n.doubleValue}.toSeq;Some((coverages++Map("scope"->"live_service","feedback_events"->size),size,if(observed.isEmpty)0d else observed.sum/observed.size,"Live feedback signal coverage"))}}
 private def latency(live:R):R={val f=obj(live.getOrElse("latency",null));if(f.isEmpty)return unavailable("missing live measurement snapshot");if(f.getOrElse("availability",null)!="available")return unavailable("live latency measurement unavailable")
  val unit=f.getOrElse("unit","milliseconds");val rows=Seq("endpoints"->"endpoint","stages"->"stage").flatMap{case(key,scope)=>obj(f.getOrElse(key,null)).toSeq.sortBy(_._1).map{case(name,v)=>val values=obj(v);Map[String,Any]("scope"->scope,"name"->name,"unit"->unit,"p50"->values.getOrElse("p50",null),"p95"->values.getOrElse("p95",null),"p99"->values.getOrElse("p99",null),"count"->values.getOrElse("count",null),"error_rate"->(if(scope=="endpoint")values.getOrElse("errorRate",null)else null),"timeout_rate"->(if(scope=="endpoint")values.getOrElse("timeoutRate",null)else null))}}
  if(rows.isEmpty)return unavailable("missing live latency measurements");val requests=rows.filter(_("scope")=="endpoint").flatMap(r=>n(r,"count")).sum.toInt;if(requests<=0)return unavailable("no live requests recorded")
  available(s"Live request and stage latency ($unit)",rows,requests,rows.count(r=>n(r,"count").exists(_!=0)).toDouble/rows.size)
 }
}
